Creates a shallow copy of the current Object.
protected:
System::Object ^ MemberwiseClone();
protected object MemberwiseClone();
member this.MemberwiseClone : unit -> obj
Protected Function MemberwiseClone () As Object
Returns
A shallow copy of the current Object.
Examples
The following example illustrates the MemberwiseClone method. It defines a ShallowCopy
method that calls the MemberwiseClone method to perform a shallow copy operation on a Person
object. It also defines a DeepCopy
method that performs a deep copy operation on a Person
object.
using System;
public class IdInfo
{
public int IdNumber;
public IdInfo(int IdNumber)
{
this.IdNumber = IdNumber;
}
}
public class Person
{
public int Age;
public string Name;
public IdInfo IdInfo;
public Person ShallowCopy()
{
return (Person)MemberwiseClone();
}
public Person DeepCopy()
{
Person other = (Person)MemberwiseClone();
other.IdInfo = new IdInfo(IdInfo.IdNumber);
return other;
}
}
public class Example
{
public static void Main()
{
// Create an instance of Person and assign values to its fields.
Person p1 = new()
{
Age = 42,
Name = "Sam",
IdInfo = new IdInfo(6565)
};
// Perform a shallow copy of p1 and assign it to p2.
Person p2 = p1.ShallowCopy();
// Display values of p1, p2
Console.WriteLine("Original values of p1 and p2:");
Console.WriteLine(" p1 instance values: ");
DisplayValues(p1);
Console.WriteLine(" p2 instance values:");
DisplayValues(p2);
// Change the value of p1 properties and display the values of p1 and p2.
p1.Age = 32;
p1.Name = "Frank";
p1.IdInfo.IdNumber = 7878;
Console.WriteLine("\nValues of p1 and p2 after changes to p1:");
Console.WriteLine(" p1 instance values: ");
DisplayValues(p1);
Console.WriteLine(" p2 instance values:");
DisplayValues(p2);
// Make a deep copy of p1 and assign it to p3.
Person p3 = p1.DeepCopy();
// Change the members of the p1 class to new values to show the deep copy.
p1.Age = 39;
p1.Name = "George";
p1.IdInfo.IdNumber = 8641;
Console.WriteLine("\nValues of p1 and p3 after changes to p1:");
Console.WriteLine(" p1 instance values: ");
DisplayValues(p1);
Console.WriteLine(" p3 instance values:");
DisplayValues(p3);
}
public static void DisplayValues(Person p)
{
Console.WriteLine($" Name: {p.Name:s}, Age: {p.Age:d}");
Console.WriteLine($" Value: {p.IdInfo.IdNumber:d}");
}
}
